-- 大白兔 game55 / TCP9212 / COM8550,8551 / cardAction20。先执行结构迁移，再部署三端，最后启用。
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS cardgamecfg (
 GAME_ID int NOT NULL, TableIndex int NOT NULL, CfgJson mediumtext NOT NULL,
 PRIMARY KEY(GAME_ID,TableIndex)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
SET @GID=55;
SET @GNAME=CONVERT(0xE5A4A7E799BDE58594 USING utf8mb4);
INSERT INTO games(GameId,Name,Enable,GameType,Num) SELECT 55,@GNAME,0,1,0 FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM games WHERE GameId=55);
INSERT INTO userrobotnum(GameId,Name,Enable,GameType,Num) SELECT 55,@GNAME,0,1,0 FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM userrobotnum WHERE GameId=55);
INSERT INTO paragame(ID,ROOM_MAX,PLY_MAX) SELECT 55,1,1000 FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM paragame WHERE ID=55);
INSERT INTO pararoom(ID,GAME_ID,NUM,BET_MIN,BET_MAX,EX_COIN,COIN_SC,COIN_NEED,scoreSwitch,Game_Mo,TableName,MaxSeats,IdleFireTimeoutSec,IdleFireKickEnabled,Enabled,MinBetUnits,MaxBetUnits)
SELECT 55000,55,3,200,4000,2000,100,1,200,1,@GNAME,1,0,1,1,2000,40000 FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM pararoom WHERE ID=55000);
INSERT INTO paracard(ID,GAME_ID,DIF,HYPE_TYPE) SELECT 55000+t.n,55,'0000000000000000',0 FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2)t WHERE NOT EXISTS(SELECT 1 FROM paracard WHERE ID=55000+t.n);
INSERT INTO roomtableconfig(GAME_ID,RoomIndex,TableIndex,TableName,Enabled,OneCoinScore,BetMin,BetMax,CoinsNeed,IdleFireTimeoutSec,IdleFireKickEnabled,MaxSeats,MinBetUnits,GunPowerStep)
SELECT 55,0,t.n,CONCAT(@GNAME,t.n+1),1,100,200,4000,1,0,1,1,2000,2000 FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2)t WHERE NOT EXISTS(SELECT 1 FROM roomtableconfig WHERE GAME_ID=55 AND TableIndex=t.n);
INSERT INTO roomtableconfig_card(GAME_ID,RoomIndex,TableIndex,ExCoin,ScoreSwitch,GameMo,MaxBetUnits)
SELECT 55,0,t.n,2000,200,1,40000 FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2)t WHERE NOT EXISTS(SELECT 1 FROM roomtableconfig_card WHERE GAME_ID=55 AND TableIndex=t.n);
INSERT INTO cardgamecfg(GAME_ID,TableIndex,CfgJson) SELECT 55,t.n,CONVERT( USING utf8mb4) FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2)t WHERE NOT EXISTS(SELECT 1 FROM cardgamecfg WHERE GAME_ID=55 AND TableIndex=t.n);
COMMIT;
